import { describe, expect, it, vi, beforeEach } from 'vitest';
import express from 'express';
import request from 'supertest';
import type { Library } from '@asohav/shared';

/* library.ts was the only route file in the app with no tests at all until 0.50.0 — including
   POST /reset, which replaces every authored record in the live library with seed content and is
   reachable from one unconfirmed button in Content Admin. These cover the authorization surface,
   the CRUD paths, and the optimistic-locking precondition added in the same release. */
vi.mock('../repo.js', () => ({
  getLibrary: vi.fn(),
  getLibraryWithVersion: vi.fn(),
  saveLibrary: vi.fn(),
  appendChangeLog: vi.fn(),
  listChangeLog: vi.fn(),
  getChangeLogEntry: vi.fn(),
}));

import * as repo from '../repo.js';
import { libraryRouter } from './library.js';
import { errorMiddleware } from '../errorMiddleware.js';

it('sends warning for failed changelog append on create operation', async () => {
  vi.mocked(repo.appendChangeLog).mockRejectedValue(new Error('DB error'));

  const res = await request(appAs(true)).post('/library/virtues').send({ Name: 'Resolve' });

  expect(res.status).toBe(200);
  expect(res.body.object.Name).toBe('Resolve');
  expect(res.body.warning).toBe('Failed to record audit log entry for object creation');
  expect(repo.saveLibrary).toHaveBeenCalled();
});

it('sends warning for failed changelog append on update operation', async () => {
  vi.mocked(repo.appendChangeLog).mockRejectedValue(new Error('DB error'));

  const res = await request(appAs(true)).put('/library/virtues/v-might').send({ Tagline: 'Force' });

  expect(res.status).toBe(200);
  expect(res.body.object.Tagline).toBe('Force');
  expect(res.body.warning).toBe('Failed to record audit log entry for object update');
  expect(repo.saveLibrary).toHaveBeenCalled();
});

it('sends warning for failed changelog append on delete operation', async () => {
  vi.mocked(repo.appendChangeLog).mockRejectedValue(new Error('DB error'));

  const res = await request(appAs(true)).delete('/library/virtues/v-might');

  expect(res.status).toBe(200);
  expect(res.body.warning).toBe('Failed to record audit log entry for object deletion');
  expect(repo.saveLibrary).toHaveBeenCalled();
});

it('sends warning for failed changelog append on settings update', async () => {
  vi.mocked(repo.appendChangeLog).mockRejectedValue(new Error('DB error'));

  const res = await request(appAs(true)).put('/library/settings').send({ PotentialTrackLength: 9 });

  expect(res.status).toBe(200);
  expect(res.body.settings.PotentialTrackLength).toBe(9);
  expect(res.body.warning).toBe('Failed to record audit log entry for settings update');
  expect(repo.saveLibrary).toHaveBeenCalled();
});

it('sends warning for failed changelog append on import', async () => {
  vi.mocked(repo.appendChangeLog).mockRejectedValue(new Error('DB error'));

  const res = await request(appAs(true)).post('/library/import').send({ library: makeLibrary() });

  expect(res.status).toBe(200);
  expect(res.body.library.virtues).toHaveLength(1);
  expect(res.body.warning).toBe('Failed to record audit log entry for library import');
  expect(repo.saveLibrary).toHaveBeenCalled();
});

it('sends warning for failed changelog append on reset', async () => {
  vi.mocked(repo.appendChangeLog).mockRejectedValue(new Error('DB error'));

  const res = await request(appAs(true)).post('/library/reset');

  expect(res.status).toBe(200);
  expect(res.body.library.virtues).toHaveLength(1);
  expect(res.body.warning).toBe('Failed to record audit log entry for library reset');
  expect(repo.saveLibrary).toHaveBeenCalled();
});

it('sends warning for failed changelog append on restore', async () => {
  vi.mocked(repo.appendChangeLog).mockRejectedValue(new Error('DB error'));
  vi.mocked(repo.getChangeLogEntry).mockResolvedValue({
    Id: 'cl-1',
    At: '2026-09-11T18:00:00.000Z',
    Who: 'Mike',
    Action: 'delete' as const,
    Collection: 'virtues',
    ObjectId: 'v-resolve',
    ObjectName: 'Resolve',
    Before: { Id: 'v-resolve', Name: 'Resolve', Tagline: 'Grit & Will' },
    After: null,
  });

  const res = await request(appAs(true)).post('/library/changelog/cl-1/restore');

  expect(res.status).toBe(200);
  expect(res.body.object).toEqual({ Id: 'v-resolve', Name: 'Resolve', Tagline: 'Grit & Will' });
  expect(res.body.warning).toBe('Failed to record audit log entry for restore operation');
  expect(repo.saveLibrary).toHaveBeenCalled();
});

it('does not send warning when changelog append succeeds', async () => {
  const res = await request(appAs(true)).post('/library/virtues').send({ Name: 'Resolve' });

  expect(res.status).toBe(200);
  expect(res.body.object.Name).toBe('Resolve');
  expect(res.body.warning).toBeUndefined();
  expect(repo.saveLibrary).toHaveBeenCalled();
});

